def read_number(n: int) -> str:
    if n == 0:
        return "영"

    digits = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_group(num):
        """Read a group of up to 4 digits without unit suffix"""
        if num == 0:
            return ""

        result = ""

        # 천 place (thousands)
        if num >= 1000:
            thousands = num // 1000
            if thousands == 1:
                result += '천'
            else:
                result += digits[thousands] + '천'
            num %= 1000

        # 백 place (hundreds)
        if num >= 100:
            hundreds = num // 100
            if hundreds == 1:
                result += '백'
            else:
                result += digits[hundreds] + '백'
            num %= 100

        # 십 place (tens)
        if num >= 10:
            tens = num // 10
            if tens == 1:
                result += '십'
            else:
                result += digits[tens] + '십'
            num %= 10

        # 일 place (ones)
        if num > 0:
            result += digits[num]

        return result

    result = ""

    # 억 group (hundred millions to ten billions)
    eok_group = n // 100000000
    if eok_group > 0:
        result += read_group(eok_group) + '억'

    # 만 group (ten thousands to hundred thousands)
    man_group = (n // 10000) % 10000
    if man_group > 0:
        if man_group == 1:
            result += '만'
        else:
            result += read_group(man_group) + '만'

    # Ones group (0 to 9999)
    ones_group = n % 10000
    if ones_group > 0:
        result += read_group(ones_group)

    return result

